          "titleZh": "巡撫南贛·破山中賊",
          "titleEn": "Governor of Southern Gan — Quelling Mountain Bandits",
          "descZh": "受兵部尚書王瓊力薦，以左僉都御史巡撫南贛汀漳。自編選練民兵，嚴明賞罰，兩年內連破詹師富、大帽山、橫水、桶岡、浰頭諸巢，蕩平盤踞贛閩粵湘邊界數十年之巨寇；繼而頒《南贛鄉約》、設崇義縣，興立社學教化百姓。",
